// Fictional sample data standing in for an Apollo CSV export.
// Set RENAME_COLUMNS to true to simulate Apollo renaming two columns:
//   role -> job_title, company_size -> employee_count
const RENAME_COLUMNS = false;

const leads = [
  { first_name: 'Amara',  last_name: 'Okafor',  email: 'amara.okafor@example.com',  company: 'Brightline Logistics', company_size: '50-200', role: 'Ops',        seniority: 'Manager',  city: 'Lagos',     country: 'Nigeria',     industry: 'Logistics',  pain_point: 'Manual dispatch reports' },
  { first_name: 'Liam',   last_name: 'Chen',    email: 'liam.chen@example.com',     company: 'Northwind Studio',     company_size: '1-10',   role: 'Founder',    seniority: 'Founder',  city: 'Toronto',   country: 'Canada',      industry: 'Design',     pain_point: 'Client onboarding takes too long' },
  { first_name: 'Sofia',  last_name: 'Alvarez', email: 'sofia.alvarez@example.com', company: 'Kestrel Health',       company_size: '200+',   role: 'Marketing',  seniority: 'Director', city: 'Madrid',    country: 'Spain',       industry: 'Healthcare', pain_point: 'Leads go stale in the CRM' },
  { first_name: 'Daniel', last_name: 'Mwangi',  email: 'daniel.mwangi@example.com', company: 'Tidewater Labs',       company_size: '11-50',  role: 'RevOps',     seniority: 'Lead',     city: 'Nairobi',   country: 'Kenya',       industry: 'SaaS',       pain_point: 'Lead routing is manual' },
  { first_name: 'Priya',  last_name: 'Nair',    email: 'priya.nair@example.com',    company: 'Quarry Software',      company_size: '50-200', role: 'Engineering', seniority: 'VP',      city: 'Bengaluru', country: 'India',       industry: 'SaaS',       pain_point: 'No view of failed syncs' },
  { first_name: 'Tom',    last_name: 'Becker',  email: 'tom.becker@example.com',    company: 'Lumen Retail',         company_size: '11-50',  role: 'Automation', seniority: 'Manager',  city: 'Berlin',    country: 'Germany',     industry: 'Retail',     pain_point: 'Automations fail silently' },
  { first_name: 'Hannah', last_name: 'Schmidt', email: 'hannah.schmidt@example.com', company: 'Orchard Foods',       company_size: '1-10',   role: 'Sales',      seniority: 'Rep',      city: 'Vienna',    country: 'Austria',     industry: 'Food',       pain_point: 'Spreadsheet follow-ups' },
  { first_name: 'Jamal',  last_name: 'Carter',  email: 'jamal.carter@example.com',  company: 'Pinecrest Media',      company_size: '11-50',  role: 'Marketing',  seniority: 'Manager',  city: 'Austin',    country: 'USA',         industry: 'Media',      pain_point: 'Campaign reporting delays' },
  { first_name: 'Elena',  last_name: 'Petrova', email: 'elena.petrova@example.com', company: 'Bluefin Partners',     company_size: '1-10',   role: 'Finance',    seniority: 'Analyst',  city: 'Sofia',     country: 'Bulgaria',    industry: 'Finance',    pain_point: 'Invoice reconciliation' },
  { first_name: 'Noah',   last_name: 'Kim',     email: 'noah.kim@example.com',      company: 'Harbor & Vale',        company_size: '11-50',  role: 'Design',     seniority: 'Lead',     city: 'Seoul',     country: 'South Korea', industry: 'Agency',     pain_point: 'Handoff between tools' },
];

return leads.map(lead => {
  if (!RENAME_COLUMNS) return { json: lead };
  const { role, company_size, ...rest } = lead;
  return { json: { ...rest, job_title: role, employee_count: company_size } };
});

const full_name = $json.first_name + " " + $json.last_name;
const sizeQualified = ["50-200", "200+"].includes($json.company_size);
const roleQualified = ["Founder", "RevOps", "Ops", "Automation"].includes($json.role);
const qualified = sizeQualified || roleQualified;
const owner_email = qualified ? "owner@example.com" : "";
const routed = owner_email !== "";

return {
  json: {
    ...$json,
    full_name,
    qualified,
    owner_email,
    routed
  }
};

// Stand-in for the HubSpot "Create or Update contact" node.
// Replace this node with the real one. "Aggregate Outcomes" only needs
// an `id` on every item that was created or updated successfully.
return { json: { ...$json, id: 'sim-' + $json.email } };

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const leads = $('Qualify Each Lead').all().map(i => i.json).filter(l => l.routed === true);
const count = leads.length;
const to = (leads[0] && leads[0].owner_email) ? leads[0].owner_email : 'owner@example.com';
const plural = count === 1 ? '' : 's';
const subject = count + ' new qualified lead' + plural + ' - sample batch';

const cell = 'padding:8px;border-bottom:1px solid #eee;font-size:14px;vertical-align:top;';
const head = 'text-align:left;padding:8px;border-bottom:2px solid #333;font-size:12px;text-transform:uppercase;color:#555;';

let rows = '';
for (const l of leads) {
  rows += '<tr>'
    + '<td style="' + cell + '">' + esc(l.full_name) + '</td>'
    + '<td style="' + cell + '">' + esc(l.company) + ' (' + esc(l.company_size) + ')</td>'
    + '<td style="' + cell + '">' + esc(l.role) + ' - ' + esc(l.seniority) + '</td>'
    + '<td style="' + cell + '">' + esc(l.city) + ', ' + esc(l.country) + '</td>'
    + '<td style="' + cell + '">' + esc(l.email) + '</td>'
    + '<td style="' + cell + '">' + esc(l.pain_point) + '</td>'
    + '</tr>';
}

const html = '<div style="font-family:Arial,Helvetica,sans-serif;color:#222;">'
  + '<h2 style="margin:0 0 4px;">' + count + ' new qualified lead' + plural + '</h2>'
  + '<p style="margin:0 0 16px;color:#666;font-size:13px;">Sample batch - routed to ' + esc(to) + '</p>'
  + '<table style="border-collapse:collapse;width:100%;">'
  + '<thead><tr>'
  + '<th style="' + head + '">Name</th>'
  + '<th style="' + head + '">Company</th>'
  + '<th style="' + head + '">Role</th>'
  + '<th style="' + head + '">Location</th>'
  + '<th style="' + head + '">Email</th>'
  + '<th style="' + head + '">Pain point</th>'
  + '</tr></thead><tbody>' + rows + '</tbody></table></div>';

return [{ json: { from: 'leads@example.com', to: to, subject: subject, html: html } }];

// Proof of outcome: what did this run actually achieve?
const allLeads = $('Qualify Each Lead').all();
const allCrm = $('CRM Upsert').all();

const leads_in = allLeads.length;
const routed_count = allLeads.filter(i => i.json.routed === true).length;
const no_owner_count = leads_in - routed_count;
const contact_created_count = allCrm.filter(i => i.json && (i.json.id || i.json.vid)).length;
const error_count = allCrm.filter(i => i.json && (i.json.error != null || i.json.status === 'error')).length;

const execId = (typeof $execution !== 'undefined' && $execution.id) ? String($execution.id) : 'manual';

// The run itself succeeded, so status is 'ok' unless the CRM step reported errors.
// A volume check on routed_count is what catches "green but wrong".
return [{
  json: {
    ingest_version: 1,
    event_type: 'signal',
    workflow_key: 'lead-router',
    occurred_at: $now.toUTC().toISO(),
    status: error_count > 0 ? 'warn' : 'ok',
    idempotency_key: execId + '-' + Date.now(),
    provider_run_id: execId,
    metrics: { leads_in, routed_count, contact_created_count, no_owner_count, error_count },
    context: { source: 'sample-apollo-export', workflow: $workflow.name }
  }
}];
